int OauthClientsInfoDao::CreateTableMySQL(chen::IDB::ptr conn) {
    return conn->execute("CREATE TABLE IF NOT EXISTS oauth_clients("
            "`id` bigint AUTO_INCREMENT COMMENT '主键',"
            "`client_id` varchar(128) NOT NULL DEFAULT '' COMMENT '客户端 ID',"
            "`client_secret_hash` varchar(128) NOT NULL DEFAULT '' COMMENT 'client_secret 的 bcrypt 哈希',"
            "`client_name` varchar(128) NOT NULL DEFAULT '' COMMENT '客户端名称',"
            "`redirect_uris` text NOT NULL COMMENT '回调 URI 白名单（JSON 数组）',"
            "`grant_types` varchar(128) NOT NULL DEFAULT '' COMMENT '允许的 grant_type',"
            "`allowed_scopes` varchar(128) NOT NULL DEFAULT '' COMMENT '允许的 scope 列表',"
            "`client_uri` varchar(128) NOT NULL DEFAULT '' COMMENT '客户端主页',"
            "`logo_uri` varchar(128) NOT NULL DEFAULT '' COMMENT '客户端图标',"
            "`enabled` int NOT NULL DEFAULT 1 COMMENT '是否启用',"
            "`create_time` timestamp NOT NULL DEFAULT current_timestamp COMMENT '创建时间',"
            "`update_time` timestamp NOT NULL DEFAULT current_timestamp COMMENT '更新时间',"
            "PRIMARY KEY(`id`),"
            "UNIQUE KEY `oauth_clients_client_id` (`client_id`)) COMMENT='OAuth 客户端注册表'");
}

int OauthClientsInfoDao::Migrate(chen::IDB::ptr conn) {
    if (!conn) {
        ERROR(logger) << "Migrate conn is null";
        return -1;
    }

    conn->execute("CREATE TABLE IF NOT EXISTS schema_version ("
        "table_name VARCHAR(128) PRIMARY KEY, "
        "version INT NOT NULL DEFAULT 0)");

    auto verStmt = conn->prepare("SELECT version FROM schema_version WHERE table_name = ?");
    if (!verStmt) {
        ERROR(logger) << "Migrate prepare version query failed errno=" << conn->getErrno();
        return conn->getErrno();
    }
    verStmt->bindString(1, "oauth_clients");
    auto verRt = verStmt->query();
    int dbVer = 0;
    if (verRt && verRt->next()) {
        dbVer = (int)verRt->getInt64(0);
    }

    if (dbVer < 1) {
        if (CreateTableSQLite3(conn)) {
            ERROR(logger) << "Migrate v1 CreateTable failed";
            return conn->getErrno();
        }
    }

    if (dbVer == 0) {
        auto insStmt = conn->prepare("INSERT INTO schema_version (table_name, version) VALUES (?, ?)");
        if (insStmt) {
            insStmt->bindString(1, "oauth_clients");
            insStmt->bindInt32(2, 1);
            insStmt->execute();
        }
    } else {
        auto updStmt = conn->prepare("UPDATE schema_version SET version = ? WHERE table_name = ?");
        if (updStmt) {
            updStmt->bindInt32(1, 1);
            updStmt->bindString(2, "oauth_clients");
            updStmt->execute();
        }
    }
    return 0;
}

